import java.util.Objects;

class Rational {

    private final int numerator;
    private final int denominator;

    Rational(int numerator, int denominator) {
        int gcd = gcd(Math.abs(numerator), Math.abs(denominator));
        int n = numerator / gcd;
        int d = denominator / gcd;
        if (d < 0) {
            n = -n;
            d = -d;
        }
        this.numerator = n;
        this.denominator = d;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    int getNumerator() {
        return numerator;
    }

    int getDenominator() {
        return denominator;
    }

    Rational add(Rational other) {
        return new Rational(
                this.numerator * other.denominator + other.numerator * this.denominator,
                this.denominator * other.denominator);
    }

    Rational subtract(Rational other) {
        return new Rational(
                this.numerator * other.denominator - other.numerator * this.denominator,
                this.denominator * other.denominator);
    }

    Rational multiply(Rational other) {
        return new Rational(
                this.numerator * other.numerator,
                this.denominator * other.denominator);
    }

    Rational divide(Rational other) {
        return new Rational(
                this.numerator * other.denominator,
                this.denominator * other.numerator);
    }

    Rational abs() {
        return new Rational(Math.abs(this.numerator), Math.abs(this.denominator));
    }

    Rational pow(int power) {
        if (power == 0) {
            return new Rational(1, 1);
        }

        if (power > 0) {
            return new Rational(intPow(this.numerator, power), intPow(this.denominator, power));
        }

        return new Rational(intPow(this.denominator, -power), intPow(this.numerator, -power));
    }

    private static int intPow(int base, int exponent) {
        int result = 1;
        for (int i = 0; i < exponent; i++) {
            result *= base;
        }
        return result;
    }

    double exp(double exponent) {
        return Math.pow(exponent, (double) this.numerator / this.denominator);
    }

    @Override
    public String toString() {
        return String.format("%d/%d", this.getNumerator(), this.getDenominator());
    }

    @Override
    public boolean equals(Object obj) {
        if (obj instanceof Rational other) {
            return this.getNumerator() == other.getNumerator()
                    && this.getDenominator() == other.getDenominator();
        }

        return false;
    }

    @Override
    public int hashCode() {
        return Objects.hash(this.getNumerator(), this.getDenominator());
    }
}

